from pathlib import Path
import math, statistics
one={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','MSE':'M'}
def chains(p):
    d={}; seen=set(); ca={}; allatoms={}
    for line in open(p, errors='ignore'):
        if not line.startswith(('ATOM','HETATM')): continue
        rec=line[:6].strip(); res=line[17:20].strip(); ch=line[21].strip() or '_'
        try: n=int(line[22:26])
        except: continue
        ins=line[26].strip(); key=(ch,n,ins)
        if rec=='ATOM':
            if key not in seen:
                seen.add(key); d.setdefault(ch,[]).append((n,ins,res,one.get(res,'X')))
            if line[12:16].strip()=='CA':
                ca[key]=(float(line[30:38]),float(line[38:46]),float(line[46:54]),one.get(res,'X'),res)
        elif rec=='HETATM':
            pass
    return d,ca

def seq(items): return ''.join(x[3] for x in items)
def rmsd(a,b):
    # no alignment: direct coord diff
    return math.sqrt(sum((a[i]-b[i])**2 for i in range(3))/3)

targets={}
for p in sorted(Path('input_targets').glob('target*.pdb')):
    d,ca=chains(p); ch=next(iter(d)); s=seq(d[ch]); targets[p.stem]=(s,ca,ch,d[ch][0][0],d[ch][-1][0])

for t,(ts,tca,tch,lo,hi) in targets.items():
    print('\\nTARGET', t, 'len', len(ts), 'range',lo,hi)
    best=[]
    for hp in sorted(Path('experiments/target_id/rcsb_pdb_hits').glob('*.pdb')):
        d,ca=chains(hp)
        for ch,items in d.items():
            hs=seq(items)
            # exact substring
            pos=hs.find(ts)
            if pos>=0:
                nums=[x[0] for x in items[pos:pos+len(ts)]]
                # direct matching by residue numbers with target where possible
                common=[]
                diffs=[]
                for key,coord in tca.items():
                    k=(ch,key[1],key[2])
                    if k in ca and ca[k][3]==coord[3]:
                        common.append(k); diffs.append(rmsd(coord, ca[k]))
                best.append((hp.stem,ch,'exact_seq_substring',pos+1,nums[0],nums[-1],len(common),statistics.mean(diffs) if diffs else None,max(diffs) if diffs else None))
            else:
                # try sequence overlap score via shared residue numbers
                common=[]; ident=0
                for key,coord in tca.items():
                    k=(ch,key[1],key[2])
                    if k in ca:
                        common.append(k); ident += (ca[k][3]==coord[3])
                if len(common)>30:
                    diffs=[rmsd(tca[(tch,k[1],k[2])], ca[k]) for k in common if (tch,k[1],k[2]) in tca and ca[k][3]==tca[(tch,k[1],k[2])][3]]
                    best.append((hp.stem,ch,f'number_overlap_id{ident}/{len(common)}',None,None,None,len(common),statistics.mean(diffs) if diffs else None,max(diffs) if diffs else None))
    for rec in sorted(best, key=lambda x: (999 if x[7] is None else x[7], -x[6]))[:20]:
        print(' ',rec)
